require_once __DIR__.'/../includes/functions.php';admin_only();if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit('Method not allowed');}csrf_check();$id=filter_input(INPUT_POST,'id',FILTER_VALIDATE_INT);$status=$_POST['status']??'';$allowed=['Pending','Under Review','Shortlisted','Accepted','Rejected'];if(!$id||!in_array($status,$allowed,true)){flash('danger','Invalid application status.');redirect('applications.php');}$s=$pdo->prepare("UPDATE applications SET status=?,updated_at=NOW() WHERE id=?");$s->execute([$status,$id]);flash('success','Application status updated.');redirect('applications.php');
